create role anon; create role authenticated; create role service_role; create schema private;
create table public.farmers(farmer_user_id bigint primary key,bank_details jsonb);
create table public.farms(farm_id bigint primary key,farmer_user_id bigint references public.farmers);
create table public.commodities(commodity_id bigint primary key,farm_id bigint references public.farms);
create table public.cart_items(cart_item_id bigint primary key,commodity_id bigint references public.commodities);
create table public.orders(order_id bigint primary key,cart_item_id bigint references public.cart_items,order_status text,payment_status text,total_amount numeric,payment_method text,updated_at timestamptz default now());
create table public.payments(payment_id bigint generated by default as identity primary key,order_id bigint references public.orders,amount numeric,payment_method text,transaction_reference text,payment_date timestamptz,payment_status text,created_at timestamptz default now(),updated_at timestamptz default now(),collection_status text,refund_reference text,refunded_at timestamptz);
